// File name: projects/03/a/Bit.hdl
CHIP Bit {
    IN in, load;
    OUT out;
    PARTS:
    Mux(a=dffOut, b=in, sel=load, out=muxOut);
    DFF(in=muxOut, out=dffOut, out=out);
}
// File name: projects/03/a/PC.hdl
CHIP PC {
    IN in[16], load, inc, reset;
    OUT out[16];
    PARTS:
    Inc16(in=regOut, out=incOut);
    Mux16(a=regOut, b=incOut, sel=inc, out=incMux);
    Mux16(a=incMux, b=in, sel=load, out=loadMux);
    Mux16(a=loadMux, b=false, sel=reset, out=resetMux);
    Or(a=inc, b=load, out=incOrLoad);
    Or(a=incOrLoad, b=reset, out=regLoad);
    Register(in=resetMux, load=regLoad, out=regOut, out=out);
}
