CHIP Mux {
    IN a, b, sel;
    OUT out;
    PARTS:
    Not(in=sel, out=notSel);
    And(a=a, b=notSel, out=aAndNotSel);
    And(a=b, b=sel, out=bAndSel);
    Or(a=aAndNotSel, b=bAndSel, out=out);
}
// File name: projects/01/DMux8Way.hdl
CHIP DMux8Way {
    IN in, sel[3];
    OUT a, b, c, d, e, f, g, h;
    PARTS:
    DMux(in=in, sel=sel[2], a=abcd, b=efgh);
    DMux4Way(in=abcd, sel=sel[0..1], a=a, b=b, c=c, d=d);
    DMux4Way(in=efgh, sel=sel[0..1], a=e, b=f, c=g, d=h);
}
// ALU (Arithmetic Logic Unit)
// The ALU computes one of the following functions:
// x+y, x-y, y-x, 0, 1, -1, x, y, -x, -y, !x, !y,
// x+1, y+1, x-1, y-1, x&y, x|y
// based on 6 input bits (zx,nx,zy,ny,f,no)
// In addition, it computes two 1-bit outputs:
// if out==0, zr=1; else zr=0
// if out<0, ng=1; else ng=0

CHIP ALU {
    IN
        x[16], y[16],
        zx, nx, zy, ny, f, no;
    OUT
        out[16],
        zr, ng;

    PARTS:
    // Zero the inputs
    Mux16(a=x, b=false, sel=zx, out=x1);
    Mux16(a=y, b=false, sel=zy, out=y1);

    // Negate the inputs
    Not16(in=x1, out=notx);
    Not16(in=y1, out=noty);
    Mux16(a=x1, b=notx, sel=nx, out=x2);
    Mux16(a=y1, b=noty, sel=ny, out=y2);

    // Compute x+y and x&y, select with f
    Add16(a=x2, b=y2, out=addout);
    And16(a=x2, b=y2, out=andout);
    Mux16(a=andout, b=addout, sel=f, out=fout);

    // Negate the output if no=1
    Not16(in=fout, out=notfout);
    Mux16(a=fout, b=notfout, sel=no, out=out, out[0..7]=low, out[8..15]=high, out[15]=msb);

    // zr: true iff out == 0
    Or8Way(in=low, out=orlow);
    Or8Way(in=high, out=orhigh);
    Or(a=orlow, b=orhigh, out=notzr);
    Not(in=notzr, out=zr);

    // ng: true iff out < 0 (i.e. MSB is 1)
    Or(a=msb, b=false, out=ng);
}
// File name: projects/02/Inc16.hdl
CHIP Inc16 {
    IN in[16];
    OUT out[16];
    PARTS:
    Add16(a=in, b[0]=true, out=out);
}

