#!/usr/bin/env python3
"""Nand2tetris HDL simulator: parser + clocked evaluator.

Scratch verification tool (not part of the repo).

Clocking model (matches the nand2tetris hardware simulator):
  - tick: combinational logic settles with current inputs; state NOT committed.
  - tock: clocked parts (DFF, registers, memories) commit their settled inputs,
          then combinational logic re-settles.
  - ARegister/DRegister probe quirk: the official simulator shows a built-in
    register's *next* value during the "+" (tick) phase; modeled in Sim.probe().
"""
import re, os

M16 = 0xFFFF

# ---------------- HDL parsing ----------------

def strip_comments(text):
    text = re.sub(r'/\*.*?\*/', '', text, flags=re.S)
    text = re.sub(r'//[^\n]*', '', text)
    return text

def parse_ref(s):
    s = s.strip()
    m = re.match(r'^(\w+)(?:\[(\d+)(?:\.\.(\d+))?\])?$', s)
    if not m:
        raise ValueError('bad ref: %r' % s)
    if m.group(2) is None:
        return m.group(1), None, None
    lo = int(m.group(2))
    hi = int(m.group(3)) if m.group(3) is not None else lo
    return m.group(1), lo, hi

def parse_pin_decls(s):
    pins, order = {}, []
    for item in s.split(','):
        item = item.strip()
        if not item:
            continue
        m = re.match(r'^(\w+)(?:\[(\d+)\])?$', item)
        if not m:
            raise ValueError('bad pin decl: %r' % item)
        pins[m.group(1)] = int(m.group(2)) if m.group(2) else 1
        order.append(m.group(1))
    return pins, order

class ChipDef:
    __slots__ = ('name', 'inp', 'in_order', 'outp', 'out_order', 'raw_parts',
                 'parts', 'behavioral', 'commit_fn', 'volatile', 'mem_size')
    def __init__(self, name):
        self.name = name
        self.inp = {}; self.in_order = []
        self.outp = {}; self.out_order = []
        self.raw_parts = []
        self.parts = None        # None until elaborated (structural)
        self.behavioral = None   # fn(inst, vals_tuple) -> outs tuple
        self.commit_fn = None    # fn(inst) for clocked behavioral chips
        self.volatile = False    # re-eval every pass (Keyboard)
        self.mem_size = 0

class PartDef:
    __slots__ = ('chip_def', 'read_groups', 'writes')
    # read_groups: per sub-input-pin (in sub.in_order):
    #              (const_bits, ((plo, wire, wlo, wmask), ...))
    # writes: (wire, wlo, pin_idx, plo, vmask, region_keep_mask)

def parse_hdl_file(path):
    text = strip_comments(open(path).read())
    m = re.search(r'CHIP\s+(\w+)\s*\{(.*)\}', text, re.S)
    if not m:
        raise ValueError('no CHIP in %s' % path)
    cd = ChipDef(m.group(1))
    body = m.group(2)
    mi = re.search(r'\bIN\s+(.*?);', body, re.S)
    mo = re.search(r'\bOUT\s+(.*?);', body, re.S)
    if mi:
        cd.inp, cd.in_order = parse_pin_decls(mi.group(1))
    if mo:
        cd.outp, cd.out_order = parse_pin_decls(mo.group(1))
    mp = re.search(r'\bPARTS\s*:(.*)', body, re.S)
    if mp:
        for pm in re.finditer(r'(\w+)\s*\((.*?)\)\s*;', mp.group(1), re.S):
            cd.raw_parts.append((pm.group(1), pm.group(2)))
    return cd

def elaborate(cd, resolve):
    if cd.parts is not None:
        return
    cd.parts = []
    for chipname, conns in cd.raw_parts:
        sub = resolve(chipname)
        pd = PartDef()
        pd.chip_def = sub
        n_in = len(sub.in_order)
        const_bits = [0] * n_in
        wire_reads = [[] for _ in range(n_in)]
        writes = []
        for conn in conns.split(','):
            conn = conn.strip()
            if not conn:
                continue
            lhs, rhs = conn.split('=')
            pname, plo, phi = parse_ref(lhs)
            if pname in sub.inp:
                if plo is None:
                    plo, phi = 0, sub.inp[pname] - 1
                w = phi - plo + 1
                pi = sub.in_order.index(pname)
                rhs = rhs.strip()
                if rhs == 'true':
                    const_bits[pi] |= ((1 << w) - 1) << plo
                elif rhs == 'false':
                    pass
                else:
                    wname, wlo, whi = parse_ref(rhs)
                    if wlo is None:
                        wlo = 0
                    wire_reads[pi].append((plo, wname, wlo, (1 << w) - 1))
            elif pname in sub.outp:
                if plo is None:
                    plo, phi = 0, sub.outp[pname] - 1
                w = phi - plo + 1
                pi = sub.out_order.index(pname)
                wname, wlo, whi = parse_ref(rhs)
                if wname in ('true', 'false'):
                    raise ValueError('constant driven by output: %s' % conn)
                if wlo is None:
                    wlo = 0
                writes.append((wname, wlo, pi, plo, (1 << w) - 1,
                               ~(((1 << w) - 1) << wlo)))
            else:
                raise ValueError('%s: pin %s not found on %s'
                                 % (cd.name, pname, chipname))
        pd.read_groups = tuple((const_bits[i], tuple(wire_reads[i]))
                               for i in range(n_in))
        pd.writes = tuple(writes)
        cd.parts.append(pd)

# ---------------- behavioral (built-in / pre-verified) chips ----------------

def _alu(pv):
    x, y, zx, nx, zy, ny, f, no = pv
    if zx: x = 0
    if nx: x = (~x) & M16
    if zy: y = 0
    if ny: y = (~y) & M16
    o = ((x + y) & M16) if f else (x & y)
    if no: o = (~o) & M16
    return (o, 1 if o == 0 else 0, 1 if o & 0x8000 else 0)

COMB = {
    'Nand':      ([('a',1),('b',1)], [('out',1)],
                  lambda v: ((~(v[0] & v[1])) & 1,)),
    'Not':       ([('in',1)], [('out',1)], lambda v: ((~v[0]) & 1,)),
    'And':       ([('a',1),('b',1)], [('out',1)], lambda v: (v[0] & v[1],)),
    'Or':        ([('a',1),('b',1)], [('out',1)], lambda v: (v[0] | v[1],)),
    'Xor':       ([('a',1),('b',1)], [('out',1)], lambda v: (v[0] ^ v[1],)),
    'Not16':     ([('in',16)], [('out',16)], lambda v: ((~v[0]) & M16,)),
    'And16':     ([('a',16),('b',16)], [('out',16)], lambda v: (v[0] & v[1],)),
    'Or16':      ([('a',16),('b',16)], [('out',16)], lambda v: (v[0] | v[1],)),
    'Mux':       ([('a',1),('b',1),('sel',1)], [('out',1)],
                  lambda v: (v[1] if v[2] else v[0],)),
    'Mux16':     ([('a',16),('b',16),('sel',1)], [('out',16)],
                  lambda v: (v[1] if v[2] else v[0],)),
    'Or8Way':    ([('in',8)], [('out',1)], lambda v: (1 if v[0] else 0,)),
    'Mux4Way16': ([('a',16),('b',16),('c',16),('d',16),('sel',2)], [('out',16)],
                  lambda v: (v[v[4]],)),
    'Mux8Way16': ([('a',16),('b',16),('c',16),('d',16),
                   ('e',16),('f',16),('g',16),('h',16),('sel',3)], [('out',16)],
                  lambda v: (v[v[8]],)),
    'DMux':      ([('in',1),('sel',1)], [('a',1),('b',1)],
                  lambda v: (0, v[0]) if v[1] else (v[0], 0)),
    'DMux4Way':  ([('in',1),('sel',2)], [('a',1),('b',1),('c',1),('d',1)],
                  lambda v: tuple(v[0] if v[1] == i else 0 for i in range(4))),
    'DMux8Way':  ([('in',1),('sel',3)],
                  [('a',1),('b',1),('c',1),('d',1),
                   ('e',1),('f',1),('g',1),('h',1)],
                  lambda v: tuple(v[0] if v[1] == i else 0 for i in range(8))),
    'HalfAdder': ([('a',1),('b',1)], [('sum',1),('carry',1)],
                  lambda v: (v[0] ^ v[1], v[0] & v[1])),
    'FullAdder': ([('a',1),('b',1),('c',1)], [('sum',1),('carry',1)],
                  lambda v: ((v[0] + v[1] + v[2]) & 1, (v[0] + v[1] + v[2]) >> 1)),
    'Add16':     ([('a',16),('b',16)], [('out',16)],
                  lambda v: ((v[0] + v[1]) & M16,)),
    'Inc16':     ([('in',16)], [('out',16)], lambda v: ((v[0] + 1) & M16,)),
    'ALU':       ([('x',16),('y',16),('zx',1),('nx',1),('zy',1),('ny',1),
                   ('f',1),('no',1)], [('out',16),('zr',1),('ng',1)], _alu),
}

def _dff_eval(inst, pv):
    inst.cur_in = pv[0]
    return (inst.state,)

def _dff_commit(inst):
    if inst.state != inst.cur_in:
        inst.state = inst.cur_in
        inst.dirty = True

def _reg_eval(inst, pv):
    inst.cur_in, inst.cur_load = pv
    return (inst.state,)

def _reg_commit(inst):
    if inst.cur_load and inst.state != inst.cur_in:
        inst.state = inst.cur_in
        inst.dirty = True

def _screen_eval(inst, pv):
    inst.cur_in, inst.cur_load, inst.cur_addr = pv
    return (inst.mem[pv[2]],)

def _screen_commit(inst):
    if inst.cur_load and inst.mem[inst.cur_addr] != inst.cur_in:
        inst.mem[inst.cur_addr] = inst.cur_in
        inst.dirty = True

def _kbd_eval(inst, pv):
    return (inst.kb,)

def _rom_eval(inst, pv):
    return (inst.mem[pv[0]],)

CLOCKED = {
    'DFF':       ([('in',1)], [('out',1)], _dff_eval, _dff_commit, 0),
    'ARegister': ([('in',16),('load',1)], [('out',16)], _reg_eval, _reg_commit, 0),
    'DRegister': ([('in',16),('load',1)], [('out',16)], _reg_eval, _reg_commit, 0),
    'Screen':    ([('in',16),('load',1),('address',13)], [('out',16)],
                  _screen_eval, _screen_commit, 8192),
    'Keyboard':  ([], [('out',16)], _kbd_eval, None, 0),
    'ROM32K':    ([('address',15)], [('out',16)], _rom_eval, None, 32768),
}

BUILTIN_NAMES = set(CLOCKED) | {'Nand'}

def make_behavioral(name):
    cd = ChipDef(name)
    if name in COMB:
        inp, outp, fn = COMB[name]
        cd.behavioral = lambda inst, pv, f=fn: f(pv)
    elif name in CLOCKED:
        inp, outp, fn, cfn, msz = CLOCKED[name]
        cd.behavioral = fn
        cd.commit_fn = cfn
        cd.mem_size = msz
        cd.volatile = (name == 'Keyboard')
    else:
        raise KeyError('no behavioral model for ' + name)
    cd.inp = dict(inp); cd.in_order = [n for n, _ in inp]
    cd.outp = dict(outp); cd.out_order = [n for n, _ in outp]
    cd.parts = []
    return cd

# ---------------- library / instantiation ----------------

class Lib:
    def __init__(self, hdl_dirs, behavioral_names=()):
        self.defs = {}
        self.hdl_files = {}
        for d in hdl_dirs:
            for f in os.listdir(d):
                if f.endswith('.hdl'):
                    self.hdl_files[f[:-4]] = os.path.join(d, f)
        self.behavioral_names = set(behavioral_names) | BUILTIN_NAMES

    def resolve(self, name):
        cd = self.defs.get(name)
        if cd is None:
            if name in self.behavioral_names:
                cd = make_behavioral(name)
            elif name in self.hdl_files:
                cd = parse_hdl_file(self.hdl_files[name])
                elaborate(cd, self.resolve)
            else:
                raise KeyError('unknown chip ' + name)
            self.defs[name] = cd
        return cd

class Inst:
    __slots__ = ('d', 'wires', 'parts', 'last_in', 'last_outs', 'state', 'mem',
                 'kb', 'cur_in', 'cur_load', 'cur_addr', 'dirty', 'clocked',
                 'regs_cache')
    def __init__(self, d, lib):
        self.d = d
        self.wires = {}
        self.state = 0
        self.mem = [0] * d.mem_size if d.mem_size else None
        self.kb = 0
        self.cur_in = 0; self.cur_load = 0; self.cur_addr = 0
        self.dirty = True
        self.clocked = None
        self.regs_cache = None
        self.last_outs = tuple([0] * len(d.out_order))
        self.parts = [make_inst(pd.chip_def, lib) for pd in d.parts]
        self.last_in = [None] * len(self.parts)

def make_inst(cd, lib):
    return Inst(cd, lib)

# ---------------- evaluation ----------------

def eval_inst(inst, pv):
    d = inst.d
    if d.behavioral is not None:
        inst.dirty = False
        r = d.behavioral(inst, pv)
        inst.last_outs = r
        return r
    w = inst.wires
    for name, val in zip(d.in_order, pv):
        w[name] = val
    parts = inst.parts
    last_in = inst.last_in
    wget = w.get
    for _ in range(60):
        changed = False
        for i, pd in enumerate(d.parts):
            sub = parts[i]
            niv = tuple(cb | _reads(reads, wget)
                        for cb, reads in pd.read_groups)
            if niv == last_in[i] and not sub.dirty and not sub.d.volatile:
                continue
            last_in[i] = niv
            outs = eval_inst(sub, niv)
            for wname, wlo, pi, plo, vmask, kmask in pd.writes:
                bits = ((outs[pi] >> plo) & vmask) << wlo
                old = wget(wname, 0)
                nv = (old & kmask) | bits
                if nv != old:
                    w[wname] = nv
                    changed = True
        if not changed:
            break
    outs = tuple(wget(nm, 0) for nm in d.out_order)
    inst.last_outs = outs
    return outs

def _reads(reads, wget):
    v = 0
    for plo, wname, wlo, wmask in reads:
        v |= ((wget(wname, 0) >> wlo) & wmask) << plo
    return v

def clocked_list(inst):
    if inst.clocked is None:
        L = []
        def rec(x):
            if x.d.behavioral is not None:
                if x.d.commit_fn is not None:
                    L.append(x)
            else:
                for s in x.parts:
                    rec(s)
        rec(inst)
        inst.clocked = L
    return inst.clocked

def commit(inst):
    for c in clocked_list(inst):
        c.d.commit_fn(c)

# ---------------- hierarchy helpers ----------------

def find_part(inst, chipname):
    if inst.d.name == chipname:
        return inst
    for sub in inst.parts:
        r = find_part(sub, chipname)
        if r is not None:
            return r
    return None

def ram_word_dffs(ram_inst):
    """Leaf DFF instances per word, in address order (follows part decl order
    of the standard RAM8/64/512/4K/16K -> Register -> Bit -> DFF hierarchy)."""
    if ram_inst.regs_cache is None:
        out = []
        def rec(x):
            if x.d.name == 'Register':
                ds = []
                for bit in x.parts:
                    for p in bit.parts:
                        if p.d.name == 'DFF':
                            ds.append(p)
                            break
                out.append(ds)
                return
            for s in x.parts:
                rec(s)
        rec(ram_inst)
        ram_inst.regs_cache = out
    return ram_inst.regs_cache

# ---------------- top-level simulation driver ----------------

class Sim:
    def __init__(self, lib, chipname):
        self.lib = lib
        self.top = make_inst(lib.resolve(chipname), lib)
        self.d = self.top.d
        self.inputs = {n: 0 for n in self.d.in_order}
        self.inputs_dirty = True
        self.outs = self.top.last_outs
        self.cycle = 0
        self.phase = '+'
        self.kb_inst = find_part(self.top, 'Keyboard')

    def settle(self):
        pv = tuple(self.inputs[n] for n in self.d.in_order)
        self.outs = eval_inst(self.top, pv)
        self.inputs_dirty = False

    def set(self, pin, val):
        w = self.d.inp[pin]
        self.inputs[pin] = val & ((1 << w) - 1)
        self.inputs_dirty = True

    def tick(self):
        if self.inputs_dirty:
            self.settle()
        self.phase = '+'

    def tock(self):
        if self.inputs_dirty:
            self.settle()
        commit(self.top)
        self.settle()
        self.cycle += 1
        self.phase = ''

    def eval(self):
        self.settle()

    def out(self, pin):
        if self.inputs_dirty:
            self.settle()
        if pin in self.d.inp:
            return self.inputs[pin]
        return self.outs[self.d.out_order.index(pin)]

    def probe(self, name):
        m = re.match(r'^(\w+)(?:\[(\d*)\])?$', name)
        cname, idx = m.group(1), m.group(2)
        sub = find_part(self.top, cname)
        if sub is None:
            raise KeyError('internal part not found: ' + name)
        if cname in ('ARegister', 'DRegister'):
            # official-simulator quirk: during the tick ("+") phase the probe
            # shows the value the register is about to commit
            if self.phase == '+':
                return sub.cur_in if sub.cur_load else sub.state
            return sub.state
        if cname.startswith('RAM') or cname == 'Screen':
            ds = ram_word_dffs(sub)[int(idx)]
            v = 0
            for j, dff in enumerate(ds):
                v |= dff.state << j
            return v
        return sub.last_outs[sub.d.out_order.index('out')]

    def poke(self, chipname, idx, val):
        sub = find_part(self.top, chipname)
        ds = ram_word_dffs(sub)[idx]
        for j, dff in enumerate(ds):
            b = (val >> j) & 1
            if dff.state != b:
                dff.state = b
                dff.dirty = True
        self.settle()

    def load_rom(self, path):
        rom = find_part(self.top, 'ROM32K')
        data = [int(l.strip(), 2) for l in open(path) if l.strip()]
        rom.mem = data + [0] * (32768 - len(data))
        rom.dirty = True
        self.settle()

#!/usr/bin/env python3
"""Minimal nand2tetris .tst interpreter + .cmp comparator (scratch tool)."""
import re, os, sys, time
from hdsim import (Lib, Sim, strip_comments)

TOKEN_RE = re.compile(r'''
      "(?:[^"\\]|\\.)*"              # quoted string
    | %[A-Za-z][0-9A-Fa-f.]*         # %B1010 / %X2000 / %D5 / %S1.4.1 ...
    | [A-Za-z_][\w.-]*(?:\[\d*\])?   # identifier, filename, Name[i], Name[]
    | -?\d+                          # number
    | <>                             # not-equal
    | [{},;=]                        # punctuation
''', re.X)

def tokenize(text):
    return TOKEN_RE.findall(strip_comments(text))

class P:
    def __init__(self, toks):
        self.t = toks; self.i = 0
    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None
    def next(self):
        tok = self.t[self.i]; self.i += 1; return tok

def parse_num(tok):
    if tok.startswith('%B'): return int(tok[2:], 2)
    if tok.startswith('%X'): return int(tok[2:], 16)
    if tok.startswith('%D'): return int(tok[2:])
    return int(tok)

def parse_cmds(p, end=None):
    cmds = []
    while p.peek() is not None and p.peek() != end:
        tok = p.next()
        if tok == 'load':
            cmds.append(('load', p.next())); swallow(p)
        elif tok in ('output-file', 'compare-to'):
            cmds.append((tok, p.next())); swallow(p)
        elif tok == 'output-list':
            cols = []
            while p.peek() != ';':
                name = p.next(); fmt = p.next()
                cols.append((name, fmt[1] if fmt.startswith('%') else '?'))
            p.next()  # ';'
            cmds.append(('output-list', cols))
        elif tok == 'set':
            name = p.next(); val = parse_num(p.next()); swallow(p)
            cmds.append(('set', name, val))
        elif tok in ('tick', 'tock', 'eval', 'output', 'clear-echo'):
            swallow(p)
            cmds.append((tok,))
        elif tok == 'echo':
            p.next(); swallow(p)  # ignore string
        elif tok == 'repeat':
            n = int(p.next()); expect(p, '{')
            body = parse_cmds(p, '}'); p.next()
            cmds.append(('repeat', n, body))
        elif tok == 'while':
            var = p.next(); op = p.next(); val = parse_num(p.next())
            expect(p, '{')
            body = parse_cmds(p, '}'); p.next()
            cmds.append(('while', var, op, val, body))
        elif tok == 'ROM32K':
            p.next()  # 'load'
            cmds.append(('romload', p.next())); swallow(p)
        else:
            raise ValueError('unexpected token %r' % tok)
    return cmds

def swallow(p):
    if p.peek() in (',', ';'):
        p.next()

def expect(p, tok):
    got = p.next()
    if got != tok:
        raise ValueError('expected %r got %r' % (tok, got))

def run_tst(tst_path, lib):
    cmds = parse_cmds(P(tokenize(open(tst_path).read())))
    basedir = os.path.dirname(tst_path)
    sim = None
    cols = []
    rows = []
    ctx = {'cmp': None}

    def colval(name, fmt):
        if name == 'time':
            return '%d%s' % (sim.cycle, sim.phase) if sim.phase == '+' \
                else str(sim.cycle)
        if name in sim.d.inp or name in sim.d.outp:
            return sim.out(name)
        return sim.probe(name)

    def exec_cmds(cs):
        nonlocal sim, cols
        for c in cs:
            k = c[0]
            if k == 'load':
                sim = Sim(lib, c[1][:-4])
            elif k == 'compare-to':
                ctx['cmp'] = c[1]
            elif k == 'output-file':
                pass
            elif k == 'output-list':
                cols = c[1]
            elif k == 'set':
                name, val = c[1], c[2]
                m = re.match(r'^(\w+)\[(\d+)\]$', name)
                if m and m.group(1).startswith('RAM'):
                    sim.poke(m.group(1), int(m.group(2)), val & 0xFFFF)
                else:
                    sim.set(name, val)
            elif k == 'tick':
                sim.tick()
            elif k == 'tock':
                sim.tock()
            elif k == 'eval':
                sim.eval()
            elif k == 'output':
                rows.append([colval(n, f) for n, f in cols])
            elif k == 'repeat':
                for _ in range(c[1]):
                    exec_cmds(c[2])
            elif k == 'while':
                var, op, target, body = c[1], c[2], c[3], c[4]
                # simulate the user holding the requested key down
                if sim.kb_inst is not None:
                    sim.kb_inst.kb = target & 0xFFFF
                    sim.settle()
                it = 0
                while (sim.out(var) != (target & 0xFFFF)) == (op == '<>'):
                    exec_cmds(body)
                    it += 1
                    if it > 1000:
                        raise RuntimeError('while loop stuck on %s %s %s'
                                           % (var, op, target))
            elif k == 'romload':
                sim.load_rom(os.path.join(basedir, c[1]))
            elif k in ('clear-echo',):
                pass
    exec_cmds(cmds)
    return sim, cols, rows, ctx['cmp']

def parse_cmp(path):
    rows = []
    for line in open(path):
        line = line.rstrip('\n')
        if not line.strip().startswith('|'):
            continue
        cells = [c.strip() for c in line.split('|')[1:-1]]
        rows.append(cells)
    return rows[0], rows[1:]

def colwidth(sim, name):
    if name in sim.d.inp:
        return sim.d.inp[name]
    if name in sim.d.outp:
        return sim.d.outp[name]
    return 16  # internal probes (registers, RAM words, PC)

def compare(sim, cols, my_rows, cmp_rows):
    """Returns list of mismatch dicts."""
    mm = []
    if len(my_rows) != len(cmp_rows):
        mm.append({'row': -1, 'col': '(row count)',
                   'expected': len(cmp_rows), 'actual': len(my_rows)})
    for i, (mine, exp) in enumerate(zip(my_rows, cmp_rows)):
        for j, (name, fmt) in enumerate(cols):
            e = exp[j] if j < len(exp) else ''
            if e and set(e) == {'*'}:
                continue  # wildcard (e.g. outM when writeM==0)
            a = mine[j]
            if fmt == 'S':
                ok = (str(a) == e)
                shown = a
            elif fmt == 'B':
                ok = (int(e, 2) == a); shown = format(a, 'b')
            elif fmt == 'X':
                ok = (int(e, 16) == a); shown = format(a, 'x')
            else:  # D: signed decimal
                w = colwidth(sim, name)
                av = a - (1 << w) if a >= (1 << (w - 1)) else a
                ok = (int(e) == av); shown = av
            if not ok:
                mm.append({'row': i, 'time': mine[0], 'col': name,
                           'expected': e, 'actual': shown})
    return mm

def run_one(tst_path, lib, verbose=True):
    t0 = time.time()
    sim, cols, rows, cmpname = run_tst(tst_path, lib)
    hdr, cmp_rows = parse_cmp(os.path.join(os.path.dirname(tst_path), cmpname))
    mm = compare(sim, cols, rows, cmp_rows)
    dt = time.time() - t0
    status = 'PASS' if not mm else 'FAIL'
    if verbose:
        print('%-28s %s  (%d rows, %.1fs)' %
              (os.path.basename(tst_path), status, len(rows), dt))
    for m in mm[:12]:
        if m['row'] == -1:
            print('    row count mismatch: expected %s got %s'
                  % (m['expected'], m['actual']))
        else:
            print('    row %s (time=%s) col %s: expected %s, actual %s'
                  % (m['row'], m['time'], m['col'], m['expected'], m['actual']))
    if len(mm) > 12:
        print('    ... and %d more mismatches' % (len(mm) - 12))
    return not mm
